echo '--- bgpd.conf ---'; sed -n '1,260p' /etc/sonic/frr/bgpd.conf 2>/dev/null; echo '--- vtysh.conf ---'; sed -n '1,120p' /etc/sonic/frr/vtysh.conf 2>/dev/null; echo '--- sonic services ---'; docker ps --format '{{.Names}} {{.Status}}' 2>/dev/null | sed -n '1,120p'; echo '--- bgp configdb keys ---'; python3 - <<'PY'
import json
p='/etc/sonic/config_db.json'
try:
 d=json.load(open(p))
 for k,v in d.items():
  if 'BGP' in k or k in ('DEVICE_METADATA','LOOPBACK_INTERFACE','PORT','VLAN','VLAN_INTERFACE','MGMT_INTERFACE'):
   print(k)
   print(json.dumps(v, indent=2)[:12000])
except Exception as e:
 print(e)
PY
 echo '--- route-map show ---'; vtysh -c 'show route-map' 2>&1 | sed -n '1,220p'; echo '--- prefix-list show ---'; vtysh -c 'show ip prefix-list' 2>&1 | sed -n '1,220p'

echo '--- bgpd.conf ---'; sed -n '1,260p' /etc/sonic/frr/bgpd.conf 2>/dev/null; echo '--- vtysh.conf ---'; sed -n '1,120p' /etc/sonic/frr/vtysh.conf 2>/dev/null; echo '--- sonic services ---'; docker ps --format '{{.Names}} {{.Status}}' 2>/dev/null | sed -n '1,120p'; echo '--- bgp configdb keys ---'; python3 - <<'PY'
import json
p='/etc/sonic/config_db.json'
try:
 d=json.load(open(p))
 for k,v in d.items():
  if 'BGP' in k or k in ('DEVICE_METADATA','LOOPBACK_INTERFACE','PORT','VLAN','VLAN_INTERFACE','MGMT_INTERFACE'):
   print(k)
   print(json.dumps(v, indent=2)[:12000])
except Exception as e:
 print(e)
PY
 echo '--- route-map show ---'; vtysh -c 'show route-map' 2>&1 | sed -n '1,220p'; echo '--- prefix-list show ---'; vtysh -c 'show ip prefix-list' 2>&1 | sed -n '1,220p'

